@Test
public void testNoRetryAwarenessCorruptsTable() {
    // This test exists to replicate the issue the prior test validates the fix for
    // See https://github.com/apache/iceberg/issues/7151
    String namespace = createNamespace();
    String tableName = createTable(namespace);
    TableIdentifier tableId = TableIdentifier.of(namespace, tableName);
    GlueTableOperations spyOps = Mockito.spy((GlueTableOperations) glueCatalog.newTableOps(tableId));
    GlueCatalog spyCatalog = Mockito.spy(glueCatalog);
    Mockito.doReturn(spyOps).when(spyCatalog).newTableOps(Mockito.eq(tableId));
    Table table = spyCatalog.loadTable(tableId);
    // Its possible that Glue or DynamoDB might someday make changes that render the retry detection
    // mechanism unnecessary. At that time, this test would start failing while the prior one would
    // still work. If or when that happens, we can re-evaluate whether the mechanism is still
    // necessary.
    simulateRetriedCommit(spyOps, false);
    Assertions.assertThatThrownBy(() -> updateTable(table, spyOps)).as("Hidden retry causes writer to conflict with itself").isInstanceOf(CommitFailedException.class).hasMessageContaining("Glue detected concurrent update").cause().isInstanceOf(ConcurrentModificationException.class);
    Assertions.assertThatThrownBy(() -> glueCatalog.loadTable(tableId)).as("Table still accessible despite hidden retry, underlying assumptions may have changed").isInstanceOf(NotFoundException.class).hasMessageContaining("Location does not exist");
}

