@Test
public void dropTableDataDeletesExpectedFiles() {
    table.newFastAppend().appendFile(FILE_A).commit();
    table.newAppend().appendFile(FILE_B).commit();
    TableMetadata tableMetadata = readMetadataVersion(3);
    Set<Snapshot> snapshotSet = Sets.newHashSet(table.snapshots());
    Set<String> manifestListLocations = manifestListLocations(snapshotSet);
    Set<String> manifestLocations = manifestLocations(snapshotSet, table.io());
    Set<String> dataLocations = dataLocations(snapshotSet, table.io());
    Set<String> metadataLocations = metadataLocations(tableMetadata);
    Assertions.assertThat(manifestListLocations).as("should have 2 manifest lists").hasSize(2);
    Assertions.assertThat(metadataLocations).as("should have 3 metadata locations").hasSize(3);
    FileIO fileIO = Mockito.mock(FileIO.class);
    Mockito.when(fileIO.newInputFile(Mockito.anyString())).thenAnswer(invocation -> table.io().newInputFile(invocation.getArgument(0)));
    Mockito.when(fileIO.newInputFile(Mockito.anyString(), Mockito.anyLong())).thenAnswer(invocation -> table.io().newInputFile(invocation.getArgument(0), invocation.getArgument(1)));
    CatalogUtil.dropTableData(fileIO, tableMetadata);
    ArgumentCaptor<String> argumentCaptor = ArgumentCaptor.forClass(String.class);
    Mockito.verify(fileIO, Mockito.times(manifestListLocations.size() + manifestLocations.size() + dataLocations.size() + metadataLocations.size())).deleteFile(argumentCaptor.capture());
    List<String> deletedPaths = argumentCaptor.getAllValues();
    Assertions.assertThat(deletedPaths).as("should contain all created manifest lists").containsAll(manifestListLocations);
    Assertions.assertThat(deletedPaths).as("should contain all created manifests").containsAll(manifestLocations);
    Assertions.assertThat(deletedPaths).as("should contain all created data").containsAll(dataLocations);
    Assertions.assertThat(deletedPaths).as("should contain all created metadata locations").containsAll(metadataLocations);
}

