    assertThat(ops.current().schema().columns()).hasSize(2);
    HiveTableOperations spyOps = spy(ops);
    // Simulate a communication error after a successful commit
    doAnswer(i -> {
        org.apache.hadoop.hive.metastore.api.Table tbl = i.getArgument(0, org.apache.hadoop.hive.metastore.api.Table.class);
        String location = i.getArgument(2, String.class);
        ops.persistTable(tbl, true, location);
        throw new LockException("Datacenter on fire");
    }).when(spyOps).persistTable(any(), anyBoolean(), any());
    assertThatThrownBy(() -> spyOps.commit(metadataV2, metadataV1)).hasMessageContaining("Failed to heartbeat for hive lock while").isInstanceOf(CommitStateUnknownException.class);
    ops.refresh();
    assertThat(ops.current().location()).as("Current metadata should have changed to metadata V1").isEqualTo(metadataV1.location());
    assertThat(metadataFileExists(ops.current())).as("Current metadata file should still exist").isTrue();
}

@Test
public void writerIsClosedAfterTaskCommitFailure() throws IOException {
    HiveIcebergOutputCommitter committer = new HiveIcebergOutputCommitter();
    HiveIcebergOutputCommitter failingCommitter = Mockito.spy(committer);
    ArgumentCaptor<TaskAttemptContextImpl> argumentCaptor = ArgumentCaptor.forClass(TaskAttemptContextImpl.class);
    String exceptionMessage = "Commit task failed!";
    Mockito.doThrow(new RuntimeException(exceptionMessage)).when(failingCommitter).commitTask(argumentCaptor.capture());
    Table table = table(temp.getRoot().getPath(), false);
    JobConf conf = jobConf(table, 1);
    Assertions.assertThatThrownBy(() -> writeRecords(table.name(), 1, 0, true, false, conf, failingCommitter)).isInstanceOf(RuntimeException.class).hasMessage(exceptionMessage);
    Assert.assertEquals(1, argumentCaptor.getAllValues().size());
    TaskAttemptID capturedId = TezUtil.taskAttemptWrapper(argumentCaptor.getValue().getTaskAttemptID());
    // writer is still in the map after commitTask failure
    Assert.assertNotNull(getWriters(capturedId));
    failingCommitter.abortTask(new TaskAttemptContextImpl(conf, capturedId));
    // abortTask succeeds and removes writer
    Assert.assertNull(getWriters(capturedId));
}

