    // Although an exception is thrown here, write and commit have succeeded
    Assertions.assertThatThrownBy(() -> df2.select("id", "data").sort("data").write().format("org.apache.iceberg.spark.source.ManualSource").option(ManualSource.TABLE_NAME, manualTableName).mode(SaveMode.Append).save(targetLocation)).isInstanceOf(CommitStateUnknownException.class).hasMessageStartingWith("Datacenter on Fire");
    // Since write and commit succeeded, the rows should be readable
    Dataset<Row> result = spark.read().format("iceberg").load(targetLocation);
    List<SimpleRecord> actual = result.orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    Assert.assertEquals("Number of rows should match", records.size() + records2.size(), actual.size());
    Assertions.assertThat(actual).describedAs("Result rows should match").containsExactlyInAnyOrder(ImmutableList.<SimpleRecord>builder().addAll(records).addAll(records2).build().toArray(new SimpleRecord[0]));
}

